/**
 * Zcom icon set (owner, 2026-11-25): the 139 filled glyphs from the "5.2–5.5 · Icons · Library 1–4" boards, cut
 * from their 32px frames. Generated from the board SVGs: to change a glyph, re-cut it from the board, not by hand.
 *
 * Built with react-icons GenIcon, so each glyph takes the same props as a react-icons icon (size, color, title,
 * className) and fills with currentColor. The viewBox adds 2 units round the 32px frame so a glyph sits at the same
 * optical size as the outline icons it replaced (the boards draw edge to edge). Use them through icons.ts.
 */
import { GenIcon, type IconType } from "react-icons";

type Part = string | [d: string, evenOdd: true];

const glyph = (parts: Part[]): IconType =>
  GenIcon({
    tag: "svg",
    attr: { viewBox: "-2 -2 36 36", fill: "currentColor" },
    child: parts.map((part) => {
      const attr: Record<string, string> =
        typeof part === "string" ? { d: part } : { d: part[0], fillRule: "evenodd", clipRule: "evenodd" };
      return { tag: "path", attr, child: [] };
    }),
  });

